(()=>{
'use strict';
const {questions,chapters}=window.QUIZ_DATA,E=window.QuizEngine,$=s=>document.querySelector(s);
const icons={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V10Zm6 11v-8h6v8',book:'M12 5C8 2 3 4 3 4v15s5-2 9 1c4-3 9-1 9-1V4s-5-2-9 1Zm0 0v15',exam:'M7 4H5v17h14V4h-2M9 3h6v4H9zM8 11h8m-8 4h8',bulb:'M9 18h6m-6 3h6M8 14a7 7 0 1 1 8 0c-1 1-1 2-1 2H9s0-1-1-2Z',bookmark:'M6 3h12v18l-6-4-6 4V3Z',history:'M3 11a9 9 0 1 1 2 7M3 4v7h7m2-4v6l4 2',arrow:'M4 12h16m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',search:'M21 21l-5-5m2-6a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',clock:'M12 7v5l3 2m6-2a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',shuffle:'m3 4 18 16m-4 0h4v-4M3 20l6-6m5-5 7-5m-4 0h4v4',close:'m6 6 12 12M6 18 18 6',flag:'M5 21V3m0 1h14l-3 4 3 4H5',back:'M20 12H4m6-6-6 6 6 6'};
const ic=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.book}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem('swd-study-v1-'+k))??f}catch{return f}};
let storageWarn=false;const save=(k,v)=>{try{localStorage.setItem('swd-study-v1-'+k,JSON.stringify(v))}catch{if(!storageWarn){storageWarn=true;toast('Trình duyệt không cho lưu dữ liệu. Tiến độ chỉ giữ trong phiên này.')}}};
let sets=read('sets',null);if(!Array.isArray(sets)||sets.length!==20||sets.some(s=>s.ids?.length!==60||new Set(s.ids).size!==60||s.ids.some(id=>!questions.some(q=>q.id===id)))){sets=E.generate(questions);save('sets',sets)}
let bookmarks=read('bookmarks',[]),history=read('history',[]),mastery=read('mastery',{}),session=read('session',null);
if(session&&(!Array.isArray(session.ids)||session.ids.some(id=>!questions.some(q=>q.id===id))||!session.answers))session=null;
const qmap=new Map(questions.map(q=>[q.id,q]));
const tip=q=>q.tip||window.TIPS[q.chapter]?.[q.number-1]||'';
const title=c=>chapters.find(x=>x.id===c)?.title||'';
const wrongIds=()=>Object.keys(mastery).filter(id=>mastery[id]===false).map(Number);
let route='home',bankPage=1,bankSearch='',bankChapter='',tipSearch='',tipChapter='',resultFilter='all',selectedResult=null,toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function dialog(html){const d=$('#dialog');d.innerHTML=html;if(!d.open)d.showModal()}
function closeDialog(){$('#dialog').close()}
function nav(){const items=[['home','home','Tổng quan'],['exams','exam','Luyện đề'],['bank','book','Ngân hàng câu hỏi'],['tips','bulb','Mẹo ghi nhớ'],['saved','bookmark','Câu đã lưu'],['history','history','Lịch sử làm bài']];$('#navigation').innerHTML=items.map(([key,icon,label])=>`<a href="#${key}" aria-label="${label}" class="nav-item ${route===key?'active':''}" ${route===key?'aria-current="page"':''}>${ic(icon)}<span>${label}</span>${key==='exams'?'<span class="count">20</span>':''}</a>`).join('');$('#breadcrumb').innerHTML=`Không gian ôn tập <span>/</span> ${esc(items.find(i=>i[0]===route)?.[2]|| (route==='quiz'?'Đang làm bài':'Kết quả'))}`}
function heading(eyebrow,headline,sub,action=''){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${headline}</h1><p class="subtitle">${sub}</p></div>${action}</div>`}
function sourceNote(){return `<div class="source-note"><strong>Minh bạch nguồn câu hỏi:</strong> File Word ghi 202 câu nhưng có 198 câu thực tế. Bộ học gồm <strong>198 câu gốc + 4 câu bổ sung</strong> ở Chapter 5, có nhãn riêng. Đáp án câu gốc giữ theo tài liệu; mẹo là gợi ý ôn tập, không thay thế việc hiểu bài.</div>`}
function statCards(values){return `<div class="stats">${values.map(([icon,value,label])=>`<div class="stat"><div class="stat-icon">${ic(icon)}</div><div><div class="stat-value">${value}</div><div class="stat-label">${label}</div></div></div>`).join('')}</div>`}
function examCard(s){const latest=history.find(h=>h.code===s.code&&h.kind==='exam'&&JSON.stringify(h.ids)===JSON.stringify(s.ids));return `<article class="exam-card"><span class="exam-code">PRACTICE TEST</span><span class="exam-symbol">${ic('exam')}</span><h3>Mã đề ${s.code}</h3><div class="exam-meta">60 câu hỏi <span>·</span> 20 chương</div><span class="status-label ${latest?'done':''}">${latest?`Đã làm · ${latest.correct}/60`:'Sẵn sàng luyện tập'}</span><button class="text-link" data-action="exam" data-code="${s.code}">Bắt đầu làm bài ${ic('arrow')}</button></article>`}
function home(){const correct=Object.values(mastery).filter(Boolean).length;const last=history[0];return heading('MỖI NGÀY MỘT CHÚT, VỮNG HƠN MỘT CHÚT','Sẵn sàng chinh phục SWD301?','Một góc nhỏ để ôn kiến thức, luyện đề và ghi nhớ những điều quan trọng.',`<div class="date-badge">${ic('book')} &nbsp; Học theo nhịp của bạn</div>`)+`<section class="hero"><div class="hero-copy"><span class="mini-pill">YOUR NEXT CHAPTER STARTS HERE</span><h2>Ôn tập có lộ trình.<br><em>Tự tin trong từng câu hỏi.</em></h2><p>202 câu hỏi, 20 mã đề và những mẹo nhớ thật gọn.<br>Chọn một đề, bắt đầu với 60 câu hôm nay.</p><div class="flex"><button class="btn" data-action="${session?'resume':'exam'}" data-code="01">${session?'Tiếp tục bài đang làm':'Luyện đề ngay'} ${ic('arrow')}</button><a class="btn ghost" href="#bank">Khám phá câu hỏi</a></div></div><div class="hero-art" aria-hidden="true"><div class="art-orbit"></div><div class="art-orbit two"></div><div class="art-star">✦</div><div class="paper"><div class="paper-top"><span>SWD301</span>${ic('book')}</div><strong>A little practice,<br>a lot of confidence.</strong><div class="paper-line"></div><div class="paper-line" style="width:75%"></div><div class="paper-option"><i></i>Understand the concept</div><div class="paper-option yes"><i>✓</i>Remember the keyword</div><div class="paper-option"><i></i>Keep moving forward</div></div><div class="art-chip">✦ &nbsp; Mỗi câu hỏi, một bước tiến</div></div></section>`+statCards([['book','202','Câu hỏi trong ngân hàng'],['exam','20','Mã đề ngẫu nhiên'],['clock','60','Câu hỏi trong mỗi đề'],['check',correct,'Câu đã trả lời đúng gần nhất']])+`<div class="home-grid"><section><div class="section-head"><div><h2>Chọn một đề, bắt đầu thôi</h2><p>Mỗi đề là một cơ hội để hiểu bài hơn.</p></div><a class="text-link" href="#exams">Tất cả 20 mã đề ${ic('arrow')}</a></div><div class="exam-grid">${sets.slice(0,4).map(examCard).join('')}</div><div class="section-space"><div class="section-head"><h2>Nhịp học của bạn</h2><a class="text-link" href="#history">Xem lịch sử ${ic('arrow')}</a></div>${last?historyRow(last):`<div class="empty">${ic('history')}<h3>Hành trình bắt đầu từ câu đầu tiên</h3>Làm một đề để theo dõi kết quả của bạn ở đây.</div>`}</div></section><aside class="tips-card"><div class="eyebrow">✦ LITTLE TIPS, BIG DIFFERENCE</div><h3>Nhìn từ khóa, nhớ ý chính</h3><div class="tip-row"><b>Validation vs. Verification</b>Right system vs. System right.</div><div class="tip-row"><b>PIM vs. PSM</b>Chưa chọn vs. Đã chọn nền tảng.</div><div class="tip-row"><b>Composition vs. Aggregation</b>Quan hệ whole/part mạnh vs. yếu.</div><a class="text-link" href="#tips">Khám phá tất cả mẹo ${ic('arrow')}</a></aside></div>`+sourceNote()}
function exams(){return heading('LUYỆN TẬP ĐỂ TIẾN BỘ','20 mã đề. 20 lần vững hơn.','Mỗi đề gồm 60 câu không trùng, lấy từ toàn bộ ngân hàng. Các đề có thể trùng câu với nhau.',`<button class="btn secondary" data-action="regenerate">${ic('shuffle')} Tạo lại 20 mã đề</button>`)+`<div class="source-note" style="margin:0 0 24px">Các mã đề được tạo ngẫu nhiên một lần và lưu trên trình duyệt này. Bạn có thể chọn thời gian khi bắt đầu. Chế độ thi chỉ hiện đáp án và mẹo sau khi nộp bài.</div><div class="exam-grid">${sets.map(examCard).join('')}</div>`+sourceNote()}
function filters(kind){const search=kind==='tips'?tipSearch:bankSearch,ch=kind==='tips'?tipChapter:bankChapter;return `<div class="toolbar"><div class="search">${ic('search')}<input id="${kind}-search" type="search" placeholder="${kind==='tips'?'Tìm mẹo, từ khóa…':'Tìm câu hỏi, đáp án hoặc từ khóa…'}" value="${esc(search)}" aria-label="Tìm kiếm"></div><select id="${kind}-chapter" aria-label="Lọc theo chương"><option value="">Tất cả 20 chương</option>${chapters.map(c=>`<option value="${c.id}" ${String(c.id)===ch?'selected':''}>Ch ${c.id} · ${esc(c.title)}</option>`).join('')}</select></div>`}
function filtered(list,search,ch){const s=search.toLocaleLowerCase('vi');return list.filter(q=>(!ch||q.chapter===+ch)&&(`${q.text} ${q.options.join(' ')} ${tip(q)}`).toLocaleLowerCase('vi').includes(s))}
function meta(q){return `<div class="question-meta"><span class="chapter-tag">Chapter ${q.chapter}</span><span>Câu ${q.number} · ${esc(title(q.chapter))}</span>${q.supplemental?'<span class="extra-tag">Câu bổ sung</span>':''}<button class="icon-btn ${bookmarks.includes(q.id)?'on':''}" data-action="bookmark" data-id="${q.id}" title="${bookmarks.includes(q.id)?'Bỏ lưu câu hỏi':'Lưu câu hỏi'}" aria-label="${bookmarks.includes(q.id)?'Bỏ lưu câu hỏi':'Lưu câu hỏi'}" aria-pressed="${bookmarks.includes(q.id)}">${ic('bookmark')}</button></div>`}
function bankCard(q){return `<article class="bank-card">${meta(q)}<h3>${esc(q.text)}</h3><details><summary class="text-link">Xem đáp án & mẹo ghi nhớ</summary><div class="reveal">${q.options.map((o,i)=>`<div class="review-option ${i===q.answer?'right':''}">${String.fromCharCode(65+i)}. ${esc(o)} ${i===q.answer?'✓':''}</div>`).join('')}<div class="tip-text">✦ <strong>Mẹo nhớ:</strong> ${esc(tip(q))}</div></div></details></article>`}
function bank(saved=false){let list=filtered(saved?questions.filter(q=>bookmarks.includes(q.id)):questions,bankSearch,bankChapter);const pages=Math.max(1,Math.ceil(list.length/12));bankPage=Math.min(bankPage,pages);return heading(saved?'DÀNH CHO LẦN ÔN TẬP TIẾP THEO':'KIẾN THỨC TRONG TẦM TAY',saved?'Những câu bạn muốn nhớ.':'Ngân hàng 202 câu hỏi.',saved?'Lưu câu khó, quay lại khi cần và luyện thêm một lần.':'Giữ nguyên câu hỏi tiếng Anh. Hiểu nhanh hơn với mẹo tiếng Việt.',`<button class="btn" data-action="practice-filtered" ${!list.length?'disabled':''}>${ic('book')} Ôn ${list.length} câu ${ic('arrow')}</button>`)+filters('bank')+`<div class="section-head"><span class="quiet">${list.length} câu hỏi${bankChapter?` · Chapter ${bankChapter}`:''}</span><span class="quiet">Bấm biểu tượng dấu trang để lưu</span></div><div class="bank-list">${list.length?list.slice((bankPage-1)*12,bankPage*12).map(bankCard).join(''):`<div class="empty">${ic(saved?'bookmark':'search')}<h3>${saved?'Chưa có câu hỏi phù hợp được lưu':'Không tìm thấy câu hỏi'}</h3>${saved?'Lưu câu từ ngân hàng hoặc khi làm bài.':'Thử từ khóa khác hoặc chọn tất cả chương.'}</div>`}</div>${pages>1?`<div class="pagination"><button class="btn secondary" data-action="page" data-page="${bankPage-1}" ${bankPage===1?'disabled':''}>← Trước</button><span>${bankPage} / ${pages}</span><button class="btn secondary" data-action="page" data-page="${bankPage+1}" ${bankPage===pages?'disabled':''}>Sau →</button></div>`:''}`+(saved?'':sourceNote())}
function tipsPage(){const list=filtered(questions,tipSearch,tipChapter);return heading('ÍT CHỮ HƠN, NHỚ NHIỀU HƠN','Bắt từ khóa. Nắm ý chính.','Mẹo giúp gợi nhớ kiến thức, không phải quy tắc đoán đáp án. Lưu ý các câu có NOT / DOES NOT.')+filters('tips')+`<p class="quiet">${list.length} mẹo theo từng câu hỏi</p><div class="tip-grid">${list.map(q=>`<article class="tip-tile">${meta(q)}<h3>${esc(q.text)}</h3><p>✦ ${esc(tip(q))}</p></article>`).join('')}</div>${false?'<p class="quiet mt">Chọn một chương hoặc nhập từ khóa để xem chi tiết các mẹo còn lại (đang hiển thị 80 mẹo đầu).</p>':''}${!list.length?'<div class="empty">Không tìm thấy mẹo phù hợp.</div>':''}`}
function historyRow(h){return `<div class="history-row"><div class="history-icon">${ic(h.kind==='exam'?'exam':'book')}</div><div class="history-info"><strong>${h.kind==='exam'?`Mã đề ${esc(h.code)}`:'Ôn tập tự do'}</strong><br><small>${new Date(h.endedAt).toLocaleString('vi-VN')} · ${h.ids.length} câu</small></div><div class="history-score">${h.correct}<span class="quiet">/${h.ids.length}</span></div><button class="text-link" data-action="result" data-id="${h.id}">Xem lại ${ic('arrow')}</button></div>`}
function historyPage(){const wrong=wrongIds();return heading('NHÌN LẠI ĐỂ TIẾN XA HƠN','Mỗi lần luyện, một chút tiến bộ.','Xem lại đáp án, ghi nhớ từ khóa và luyện lại những câu bạn còn nhầm.',`<button class="btn" data-action="wrong" ${wrong.length?'':'disabled'}>Ôn ${wrong.length} câu sai gần nhất ${ic('arrow')}</button>`)+statCards([['exam',history.length,'Bài đã hoàn thành'],['check',Object.values(mastery).filter(Boolean).length,'Câu đúng gần nhất'],['book',wrong.length,'Câu cần ôn lại'],['bookmark',bookmarks.length,'Câu hỏi đã lưu']])+`${history.length?history.map(historyRow).join(''):'<div class="empty"><h3>Chưa có bài làm nào</h3>Hoàn thành bài ôn tập hoặc một mã đề để xem kết quả.</div>'}`}
function persist(){save('session',session)}
function askStart(code){const set=sets.find(s=>s.code===code);if(!set)return;dialog(`<div class="eyebrow">SẴN SÀNG CHƯA?</div><h2>Mã đề ${code} · 60 câu hỏi</h2><p>Chọn một đáp án cho mỗi câu. Bạn có thể đánh dấu để xem lại. Đáp án và mẹo sẽ hiện sau khi nộp bài.</p>${session?'<p style="color:var(--amber)">Bạn đang có bài làm dở. Bắt đầu bài mới sẽ thay thế tiến độ bài đó.</p>':''}<label for="duration">Thời gian làm bài</label><select id="duration"><option value="60">60 phút</option><option value="45">45 phút</option><option value="90">90 phút</option><option value="0">Không giới hạn</option></select><div class="dialog-actions"><button class="btn secondary" data-action="cancel">Để sau</button><button class="btn" data-action="confirm-exam" data-code="${code}">Bắt đầu ${ic('arrow')}</button></div>`)}
function begin(ids,kind='practice',code=null,minutes=0){session={id:crypto.randomUUID(),ids:[...ids],kind,code,answers:{},flags:[],index:0,startedAt:Date.now(),deadline:minutes?Date.now()+minutes*60000:null};persist();closeDialog();location.hash='quiz';render()}
function practice(ids){if(!ids.length)return;if(session){dialog(`<h2>Bắt đầu lượt ôn mới?</h2><p>Bạn đang có bài làm dở. Lượt ôn mới gồm ${ids.length} câu và sẽ thay thế tiến độ bài hiện tại.</p><div class="dialog-actions"><button class="btn secondary" data-action="cancel">Quay lại</button><button class="btn" id="confirm-practice">Bắt đầu ôn</button></div>`);$('#confirm-practice').onclick=()=>begin(ids)}else begin(ids)}
function quiz(){if(!session)return '<div class="empty"><h3>Chưa có bài đang làm</h3><a class="btn mt" href="#exams">Chọn mã đề</a></div>';const s=session,q=qmap.get(s.ids[s.index]),chosen=s.answers[q.id],has=Number.isInteger(chosen),show=s.kind==='practice'&&has,answered=Object.keys(s.answers).length;return heading(s.kind==='exam'?'TẬP TRUNG MỘT CHÚT, TIẾN BỘ MỘT CHÚT':'VỪA LÀM, VỪA GHI NHỚ',s.kind==='exam'?`Mã đề ${s.code}`:'Ôn tập tự do',`${s.ids.length} câu hỏi · ${s.kind==='exam'?'Đáp án được ẩn cho đến khi nộp bài':'Đáp án và mẹo hiện sau khi chọn'}`,`<button class="btn secondary" data-action="leave">Lưu & về tổng quan</button>`)+`<div class="study-layout"><section class="question-panel">${meta(q)}<div class="section-head mt"><span class="eyebrow">CÂU ${s.index+1} / ${s.ids.length}</span><button class="text-link" data-action="flag">${ic('flag')} ${s.flags.includes(q.id)?'Đã đánh dấu':'Đánh dấu xem lại'}</button></div><h2>${esc(q.text)}</h2>${q.options.map((o,i)=>`<button class="option ${chosen===i?'selected':''} ${show&&q.answer===i?'correct':''} ${show&&chosen===i&&chosen!==q.answer?'incorrect':''}" data-action="answer" data-value="${i}" ${show?'disabled':''} aria-pressed="${chosen===i}"><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(o)}</span></button>`).join('')}${show?`<div class="feedback ${chosen===q.answer?'':'bad'}">${chosen===q.answer?'✓ Chính xác!':'Đáp án đúng: '+String.fromCharCode(65+q.answer)}<div class="tip-text">✦ <strong>Mẹo nhớ:</strong> ${esc(tip(q))}</div></div>`:''}<div class="question-bottom"><button class="btn secondary" data-action="move" data-index="${s.index-1}" ${s.index===0?'disabled':''}>${ic('back')} Câu trước</button>${s.index<s.ids.length-1?`<button class="btn" data-action="move" data-index="${s.index+1}">Câu tiếp theo ${ic('arrow')}</button>`:'<button class="btn" data-action="submit">Hoàn thành bài</button>'}</div></section><aside><div class="map-card"><span class="quiet">${s.deadline?'THỜI GIAN CÒN LẠI':'THỜI GIAN ĐÃ LÀM'}</span><div class="timer" id="timer">--:--</div><div class="section-head"><h3>Tiến độ bài làm</h3><span class="quiet">${answered}/${s.ids.length}</span></div><div class="progress-track"><i style="width:${answered/s.ids.length*100}%"></i></div><div class="map-grid">${s.ids.map((id,i)=>`<button class="map-num ${Number.isInteger(s.answers[id])?'answered':''} ${s.index===i?'current':''} ${s.flags.includes(id)?'flagged':''}" data-action="move" data-index="${i}" aria-label="Câu ${i+1}${Number.isInteger(s.answers[id])?', đã trả lời':''}${s.flags.includes(id)?', đã đánh dấu':''}" ${s.index===i?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><div class="legend">■ Tím nhạt: đã chọn đáp án<br>◩ Góc vàng: đã đánh dấu xem lại</div><button class="btn" data-action="submit">${ic('check')} Nộp bài</button></div><p class="hint-note">Tiến độ tự lưu sau mỗi câu.<br>Phím 1–4: chọn đáp án · ← →: chuyển câu.<br>${s.kind==='exam'?'Đồng hồ vẫn chạy khi rời trang. Hết giờ, bài tự nộp.':'Cứ sai rồi sửa, bạn sẽ nhớ lâu hơn.'}</p></aside></div>`}
function submitPrompt(){if(!session)return;const r=E.score(session.ids,session.answers,questions);dialog(`<h2>Nộp bài và xem kết quả?</h2><p>Bạn đã trả lời <strong>${r.answered}/${r.total}</strong> câu.${r.blank?` Còn ${r.blank} câu chưa trả lời; những câu này được tính 0 điểm.`:''} ${session.flags.length?`Có ${session.flags.length} câu được đánh dấu xem lại.`:''}</p><div class="dialog-actions"><button class="btn secondary" data-action="cancel">Tiếp tục làm</button><button class="btn" data-action="confirm-submit">Nộp bài</button></div>`)}
function finish(expired=false){if(!session)return;const s=session,r=E.score(s.ids,s.answers,questions);const h={...s,...r,endedAt:Date.now(),expired};history.unshift(h);history=history.slice(0,100);for(const id of s.ids)mastery[id]=s.answers[id]===qmap.get(id).answer;save('history',history);save('mastery',mastery);session=null;save('session',null);selectedResult=h;resultFilter='all';closeDialog();location.hash='result';render();if(expired)toast('Đã hết giờ. Bài được nộp tự động.')}
function resultPage(){const h=selectedResult||history[0];if(!h)return '<div class="empty">Chưa có kết quả. <a href="#exams">Chọn mã đề để bắt đầu.</a></div>';const ids=h.ids.filter(id=>resultFilter==='all'||(resultFilter==='wrong'&&Number.isInteger(h.answers[id])&&h.answers[id]!==qmap.get(id).answer)||(resultFilter==='blank'&&!Number.isInteger(h.answers[id])));return heading('HOÀN THÀNH MỘT BƯỚC TIẾN',h.kind==='exam'?`Kết quả mã đề ${h.code}`:'Kết quả ôn tập','Xem lại câu trả lời và mẹo ghi nhớ để lần sau vững vàng hơn.')+`<section class="result-hero"><div class="eyebrow">${h.expired?'BÀI ĐƯỢC NỘP KHI HẾT GIỜ':'BÀI LÀM ĐÃ ĐƯỢC LƯU'}</div><div class="result-score">${h.correct}<span> / ${h.total} câu đúng</span></div><h2>${Math.round(h.correct/h.total*100)}% chính xác · ${(h.correct/h.total*10).toFixed(2)} / 10 điểm</h2><p>${h.wrong} câu sai · ${h.blank} câu chưa trả lời · ${Math.floor((h.endedAt-h.startedAt)/60000)} phút làm bài</p><div class="result-actions"><button class="btn" data-action="retry-result" data-id="${h.id}" ${h.correct===h.total?'disabled':''}>Ôn lại ${h.total-h.correct} câu chưa đúng ${ic('arrow')}</button><a class="btn secondary" href="#exams">Chọn đề tiếp theo</a></div></section><div class="result-tabs">${[['all','Tất cả',h.total],['wrong','Câu sai',h.wrong],['blank','Chưa trả lời',h.blank]].map(([key,label,n])=>`<button class="filter-btn ${resultFilter===key?'active':''}" data-action="result-filter" data-value="${key}">${label} (${n})</button>`).join('')}</div><div class="bank-list">${ids.length?ids.map(id=>{const q=qmap.get(id);return `<article class="bank-card">${meta(q)}<h3>${esc(q.text)}</h3>${q.options.map((o,i)=>`<div class="review-option ${q.answer===i?'right':h.answers[id]===i?'wrong':''}">${String.fromCharCode(65+i)}. ${esc(o)} ${q.answer===i?'✓ Đáp án đúng':''} ${h.answers[id]===i?'· Bạn chọn':''}</div>`).join('')}${!Number.isInteger(h.answers[id])?'<p class="quiet">Bạn chưa trả lời câu này.</p>':''}<div class="tip-text">✦ <strong>Mẹo nhớ:</strong> ${esc(tip(q))}</div></article>`}).join(''):'<div class="empty">Không có câu hỏi trong mục này.</div>'}</div>`}
function render(preserveScroll=false){const scroll=window.scrollY;route=location.hash.slice(1)||'home';if(!['home','bank','exams','tips','saved','history','quiz','result'].includes(route))route='home';nav();$('#main').innerHTML=({home,exams,bank,tips:tipsPage,saved:()=>bank(true),history:historyPage,quiz,result:resultPage}[route])();if(preserveScroll)window.scrollTo(0,scroll);else window.scrollTo(0,0);tick()}
function tick(){if(!session)return;const el=$('#timer');const remaining=session.deadline?session.deadline-Date.now():Date.now()-session.startedAt;if(session.deadline&&remaining<=0){finish(true);return}if(el){const secs=Math.max(0,Math.ceil(remaining/1000)),mins=Math.floor(secs/60);el.textContent=String(mins).padStart(2,'0')+':'+String(secs%60).padStart(2,'0');el.classList.toggle('urgent',!!session.deadline&&remaining<300000)}}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;
 if(a==='exam')askStart(b.dataset.code);
 else if(a==='confirm-exam'){const minutes=+$('#duration').value;begin(sets.find(s=>s.code===b.dataset.code).ids,'exam',b.dataset.code,minutes)}
 else if(a==='cancel')closeDialog();
 else if(a==='resume'){location.hash='quiz';render()}
 else if(a==='leave'){location.hash='home';toast('Đã lưu bài. Bạn có thể tiếp tục bất cứ lúc nào.')}
 else if(a==='bookmark'){const id=+b.dataset.id;bookmarks=bookmarks.includes(id)?bookmarks.filter(x=>x!==id):[...bookmarks,id];save('bookmarks',bookmarks);b.classList.toggle('on',bookmarks.includes(id));b.setAttribute('aria-pressed',bookmarks.includes(id));b.setAttribute('aria-label',bookmarks.includes(id)?'Bỏ lưu câu hỏi':'Lưu câu hỏi');b.title=b.getAttribute('aria-label');toast(bookmarks.includes(id)?'Đã lưu câu hỏi':'Đã bỏ lưu câu hỏi');if(route==='saved')render(true)}
 else if(a==='answer'&&session){const q=qmap.get(session.ids[session.index]);if(session.kind==='practice'&&Number.isInteger(session.answers[q.id]))return;session.answers[q.id]=+b.dataset.value;persist();render(true)}
 else if(a==='move'&&session){const i=+b.dataset.index;if(i>=0&&i<session.ids.length){session.index=i;persist();render(true)}}
 else if(a==='flag'&&session){const id=session.ids[session.index];session.flags=session.flags.includes(id)?session.flags.filter(x=>x!==id):[...session.flags,id];persist();render(true)}
 else if(a==='submit')submitPrompt();
 else if(a==='confirm-submit')finish();
 else if(a==='practice-filtered')practice(filtered(route==='saved'?questions.filter(q=>bookmarks.includes(q.id)):questions,bankSearch,bankChapter).map(q=>q.id));
 else if(a==='wrong')practice(wrongIds());
 else if(a==='retry-result'){const h=history.find(x=>x.id===b.dataset.id);if(h)practice(h.ids.filter(id=>h.answers[id]!==qmap.get(id).answer))}
 else if(a==='page'){bankPage=+b.dataset.page;render()}
 else if(a==='result'){selectedResult=history.find(x=>x.id===b.dataset.id);resultFilter='all';location.hash='result';render()}
 else if(a==='result-filter'){resultFilter=b.dataset.value;render(true)}
 else if(a==='regenerate')dialog(`<h2>Tạo lại 20 mã đề?</h2><p>Bộ mã đề hiện tại sẽ được thay bằng 20 đề ngẫu nhiên mới, mỗi đề 60 câu không trùng. Lịch sử và bài đang làm vẫn được giữ.</p><div class="dialog-actions"><button class="btn secondary" data-action="cancel">Giữ bộ hiện tại</button><button class="btn" data-action="confirm-regenerate">Tạo bộ mới</button></div>`);
 else if(a==='confirm-regenerate'){sets=E.generate(questions);save('sets',sets);closeDialog();render();toast('Đã tạo bộ 20 mã đề mới')}
});
document.addEventListener('input',ev=>{const el=ev.target;if(!['bank-search','tips-search'].includes(el.id))return;const pos=el.selectionStart,id=el.id;if(id==='bank-search'){bankSearch=el.value;bankPage=1}else tipSearch=el.value;render(true);const restored=$('#'+id);restored.focus();restored.setSelectionRange(pos,pos)});
document.addEventListener('change',ev=>{if(ev.target.id==='bank-chapter'){bankChapter=ev.target.value;bankPage=1;render(true)}else if(ev.target.id==='tips-chapter'){tipChapter=ev.target.value;render(true)}});
document.addEventListener('keydown',ev=>{if(route!=='quiz'||!session||$('#dialog').open||ev.ctrlKey||ev.metaKey||ev.altKey||['INPUT','SELECT','TEXTAREA','BUTTON'].includes(ev.target.tagName))return;if(/^[1-4]$/.test(ev.key))$(`[data-action="answer"][data-value="${+ev.key-1}"]`)?.click();else if(ev.key==='ArrowRight'||ev.key==='ArrowLeft'){ev.preventDefault();$(`[data-action="move"][data-index="${session.index+(ev.key==='ArrowRight'?1:-1)}"]`)?.click()}});
window.addEventListener('hashchange',()=>render());window.addEventListener('pageshow',tick);document.addEventListener('visibilitychange',tick);setInterval(tick,1000);render();
})();
